/// The level as ASCII rows: `.` empty, `W` the 7 wall, `8` the anchor gumball,
/// `9` an ordinary gumball. One string per row, 21 characters each.
///
/// Same glyphs as the row comments above, so `cargo run --bin board_dump` and
/// this file can be compared at a glance.
pub fn level_ascii() -> Vec<String> {
    LEVEL
        .chunks(21)
        .map(|row| {
            row.iter()
                .map(|&v| match v {
                    0 => '.',
                    7 => 'W',
                    8 => '8',
                    _ => '9',
                })
                .collect()
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn level_has_the_carts_shape() {
        assert_eq!(LEVEL.len(), 525);
        assert_eq!(LEVEL[262], 8, "the white anchor must be at the centre cell");
        let nines = LEVEL.iter().filter(|&&v| v == 9).count();
        let sevens = LEVEL.iter().filter(|&&v| v == 7).count();
        let eights = LEVEL.iter().filter(|&&v| v == 8).count();
        let zeros = LEVEL.iter().filter(|&&v| v == 0).count();
        assert_eq!((nines, sevens, eights, zeros), (36, 24, 1, 464));
    }

    #[test]
    fn every_coloured_cell_is_inside_the_mass() {
        // The level is one connected blob: 61 cells, all within 176..=348.
        for (i, &v) in LEVEL.iter().enumerate() {
            if v != 0 {
                assert!((176..=348).contains(&i), "cell {i} is outside the blob");
            }
        }
    }

    #[test]
    fn rows_are_the_ascii_shape_from_the_plan() {
        let glyph = |v: u8| match v {
            0 => '.',
            7 => 'W',
            8 => '8',
            _ => '9',
        };
        let row = |r: usize| -> String {
            LEVEL[r * 21..(r + 1) * 21]
                .iter()
                .map(|&v| glyph(v))
                .collect()
        };
        assert_eq!(row(0), ".....................");
        assert_eq!(row(8), "........WWWWW........");
        assert_eq!(row(12), "......W9998999W......");
        assert_eq!(row(16), "........WWWWW........");
        assert_eq!(row(24), ".....................");
    }

    #[test]
    fn level_ascii_is_25_rows_of_21_columns() {
        let rows = level_ascii();
        assert_eq!(rows.len(), 25);
        for (r, row) in rows.iter().enumerate() {
            assert_eq!(row.chars().count(), 21, "row {r} is {row:?}");
            assert!(
                row.chars().all(|c| ".*W89".contains(c)),
                "row {r} has an unexpected glyph: {row:?}"
            );
        }
        assert_eq!(rows[12], "......W9998999W......");
    }
}
